import sys; sys.path.insert(0,'.')
from mockweb.corpus import load
from mockweb.search import rank
c = load('corpus/sample')
TERMS = ['','company profile','headquarters city legal name','chief executive officer leadership team','founded year employees headcount','funding raised investment total','about contact','careers jobs hiring','news press release','products services customers','history incorporated registered office','investors board of directors','registered name filing record','staff workforce people numbers','solutions platform technology','suppliers partners distribution','awards recognition community','sustainability report annual','office locations global','legal entity name of record']
domains = sorted(c.companies)
totals = {}
for d in domains:
    totals[d] = {p.url for p in c.companies[d].pages if p.searchable and 0 in p.epochs}
def urls(d, q):
    return {p.url for p in rank(c.pages(0), q, 10, provider='nimble', traits=c.traits)} & totals[d]
chosen = []
covered = {d:set() for d in domains}
for step in range(1, 17):
    best = None
    for term in TERMS:
        for form in ('domain','name'):
            gain = 0
            for d in domains:
                q = (d if form=='domain' else d.split('.')[0].replace('-',' ')) + ((' '+term) if term else '')
                gain += len(urls(d,q) - covered[d])
            if best is None or gain > best[0]: best = (gain, term, form)
    gain, term, form = best
    chosen.append((form, term))
    for d in domains:
        q = (d if form=='domain' else d.split('.')[0].replace('-',' ')) + ((' '+term) if term else '')
        covered[d] |= urls(d,q)
    frac = sum(len(covered[d]) for d in domains)/sum(len(totals[d]) for d in domains)
    print(f'{step:2d} queries  coverage={frac:.3f}  +{form}:{term!r}')
